  const normalize = (value) => String(value || "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase();
  const words = (value) => normalize(value).split(/[^a-z0-9]+/).filter((w) => w.length > 3);
  const yearFrom = (value) => {
    const match = String(value || "").match(/(19|20)\d{2}/);
    return match ? match[0] : "";
  };
  const scoreMatch = (title, file, year) => {
    const titleWords = words(title);
    const haystack = normalize(file);
    if (!titleWords.length) return 0;
    const overlap = titleWords.filter((word) => haystack.includes(word)).length / titleWords.length;
    const yearBonus = year && file.startsWith(year) ? 0.25 : 0;
    return overlap + yearBonus;
  };
  const findEvidence = (title, year, type) => {
    const candidates = driveEvidence.filter((item) => !type || item.type === type);
    let best = null;
    let bestScore = 0;
    candidates.forEach((item) => {
      const score = scoreMatch(title, item.file, year);
      if (score > bestScore) {
        best = item;
        bestScore = score;
      }
    });
    return bestScore >= 0.45 ? best : null;
  };

