  const applyUserCorrection = (item) => {
    const keys = [item.driveId, item.url, item.downloadUrl, item.evidence, item.file, item.localPath].filter(Boolean).map(String);
    let correction = null;
    for (const key of keys) {
      correction = userCorrectedEvidence[key] || correction;
    }
    if (!correction) return item;
    item.name = correction.name || item.name;
    item.nameEn = correction.nameEn || correction.name || item.nameEn;
    item.institution = correction.institution || item.institution;
    if (correction.type) item.type = correction.type;
    if (correction.typeEn) item.typeEn = correction.typeEn;
    if (correction.year) item.year = correction.year;
    if (correction.month) item.month = correction.month;
    if (correction.category) item.category = correction.category;
    if (correction.recommendedUse) item.recommendedUse = correction.recommendedUse;
    return item;
  };

